-- Every control model's row-level results, unioned into one shape.
--
-- The union is explicit rather than generated by a macro over the directory. That is deliberate:
-- adding a control model without adding it here means it never reaches the variance layer, and an
-- explicit list makes that omission a visible one-line diff instead of silent absence. The
-- validator cross-checks this list against controls/ and fails when they disagree.
with unioned as (
    select as_of, control_id, subject_id, passing, reason
    from {{ ref('ctl_cui_boundary_asset_inventory') }}
    union all
    select as_of, control_id, subject_id, passing, reason
    from {{ ref('ctl_iam_cui_enclave_mfa') }}
    union all
    select as_of, control_id, subject_id, passing, reason
    from {{ ref('ctl_iam_corp_it_mfa') }}
    union all
    select as_of, control_id, subject_id, passing, reason
    from {{ ref('ctl_scrm_procurement_entity_list_screening') }}
    union all
    select as_of, control_id, subject_id, passing, reason
    from {{ ref('ctl_scrm_procurement_telecom_equipment_attestation') }}
    union all
    select as_of, control_id, subject_id, passing, reason
    from {{ ref('ctl_ir_dibnet_incident_reporting') }}
)
select * from unioned
